/**
 * ERWEITERUNG 24.09.2026 (Version 19) — "richtige Berufsbezeichnungen statt
 * Weiterbildungs-Titel, umfangreich":
 *  - role_name ist jetzt IMMER eine echte Berufsbezeichnung
 *    ("Marketingmanager/in" statt "Fachwirt fuer Marketing (IHK)"). Die
 *    Weiterbildung, ueber die man typischerweise in den Beruf kommt, steht im
 *    neuen optionalen Feld typische_weiterbildung.
 *  - role_id der 51 bestehenden Rollen ist UNVERAENDERT (die IDs tragen
 *    teils noch die alten Weiterbildungs-Namen, z. B.
 *    "wirtschaft-handelsfachwirt-ihk") — bewusst, weil Kurse im Dashboard per
 *    target_role_ids genau darauf verweisen. IDs sind interne Schluessel,
 *    nie Anzeige.
 *  - Neues optionales Feld anforderungsniveau (1 Helfer, 2 Fachkraft,
 *    3 Spezialist, 4 Experte; angelehnt an KldB 2010 der BA).
 *  - 75 neue Berufe (126 gesamt), 4 neue Bereiche: logistik, handel,
 *    produktion, gastro-service. Zwei Handelsrollen (Filialleitung,
 *    Category Management) von "wirtschaft" nach "handel" verschoben.
 *  - 126 neue Skills; Gewichte je Rolle per Generator exakt auf 100
 *    normiert und per Skript geprueft (IDs, Summen, Dubletten).
 *  Bekannt und NICHT Teil dieser Aenderung: bei 14 Alt-Rollen weicht der
 *  Skill-Name in der Rolle vom Namen in SKILLS_CATALOG ab (z. B.
 *  "ueberwachung-vitalparameter") — reine Anzeige-Inkonsistenz.
 *
 * Eigener, einfacher Skill-Katalog fuer DYD ORBIT (Version 18) — komplett
 * ueberarbeiteter Rollen-Katalog: von 74 generischen Rollen (je 5 flache
 * Skills) auf 51 Rollen, die eng an echten IHK-Fortbildungsordnungen
 * (Fachwirt, Fachkaufmann, Betriebswirt, Bilanzbuchhalter, IT-Berufsspezialist
 * etc.) bzw. an real geregelten Berufsbildern in Gesundheit/Pflege
 * (Pflegeberufereform 2020, DKG-Fachweiterbildungen, §71 SGB XI) und Handwerk
 * (HWK-Meisterpruefungen, DVS/IHK Schweissfachmann) ausgerichtet sind. Jede
 * Rolle hat jetzt 13-16 spezifische Skills statt 5 (Gewichte summieren pro
 * Rolle exakt auf 100), damit generische Fuehrungs-/Querschnittsskills wie
 * "Teamfuehrung" keine Rollen mehr bereichsuebergreifend nach oben spuelen
 * (Ausloeser: Kita-Leitung tauchte faelschlich als Top-Match in
 * Wirtschaft & Verwaltung auf, weil ihr staerkster Skill mit 33% Gewicht das
 * generische "Teamfuehrung" war). Erstellt per sechs parallelen, auf
 * echten IHK-/HWK-/DKG-Quellen recherchierenden Themen-Agenten (je einer pro
 * Bereich), anschliessend zusammengefuehrt, auf Skill-ID-Kollisionen und
 * Gewichtssummen (=100) geprueft. Migrations-Tabelle fuer alte
 * target_role_id-Zuordnungen in bestehenden Kursen: siehe Chat-Uebergabe an
 * Quentin vom 14.09.2026.
 *
 * WICHTIG: Dies ist der Datenteil. Er ist bewusst getrennt von der DB-Anbindung
 * (Supabase), damit er 1:1 sowohl als Seed-Daten fuer eine Tabelle als auch
 * (uebergangsweise oder dauerhaft) als In-Memory-Fallback im Code genutzt
 * werden kann, bis schema.sql/index.ts final abgestimmt sind.
 */

export interface CatalogSkill {
  skill_id: string;
  name: string;
  /** Zusaetzliche Suchbegriffe (z.B. aus Klammer-Zusaetzen wie "(Git)"). */
  aliases: string[];
  /**
   * Optional, additiv. Verhindert Substring-Fehltreffer bei laengeren
   * Begriffen (z.B. "Java" das eigentlich Teil von "JavaScript" ist) - steht
   * direkt nach dem Treffer einer dieser Strings, zaehlt DIESES Vorkommen
   * nicht. Siehe skillMatcher.ts, isExcludedContinuation(). Ein Skill ohne
   * dieses Feld verhaelt sich exakt wie vorher.
   */
  excludeIfFollowedBy?: string[];
  /**
   * Optional, additiv — Spiegelbild von excludeIfFollowedBy: steht direkt VOR
   * dem Treffer einer dieser Strings, zaehlt DIESES Vorkommen nicht. Fuer
   * Kollisionen, bei denen der kuerzere Begriff als SUFFIX eines laengeren,
   * fachlich anderen Begriffs auftaucht (z.B. "Fallmanagement" als Substring
   * von "Notfallmanagement"). Siehe skillMatcher.ts,
   * isExcludedPrecedingContext(). Ein Skill ohne dieses Feld verhaelt sich
   * exakt wie vorher.
   */
  excludeIfPrecededBy?: string[];
}

export interface CatalogRoleSkill {
  skill_id: string;
  name: string;
  /** Gewicht 1-100 innerhalb der Rolle (Summe pro Rolle = 100). */
  weight: number;
}

export interface CatalogRole {
  role_id: string;
  role_name: string;
  bereich_key: string;
  bereich_label: string;
  level: "Einsteiger" | "Fachkraft" | "Senior" | "Führung";
  /**
   * Optional, additiv (24.09.2026). Anforderungsniveau analog zur
   * Klassifikation der Berufe 2010 der Bundesagentur fuer Arbeit:
   * 1 = Helfer/Anlerntaetigkeit, 2 = Fachkraft (Berufsausbildung),
   * 3 = Spezialist/in (Meister, Techniker, Fachwirt, Bachelor),
   * 4 = Experte/Expertin (Leitung, Master/Diplom). Grundlage fuer die
   * Stepping-Stone-Logik; buildBereichRole() laesst Niveau 1 aus dem
   * Bereichs-Durchschnitt heraus. Pseudo-Rollen (bereich:...) haben keins.
   */
  anforderungsniveau?: 1 | 2 | 3 | 4;
  /**
   * Optional, additiv (24.09.2026). Die Weiterbildung/Pruefung, ueber die
   * man typischerweise in diesen Beruf kommt (z. B. "Fachwirt/in fuer
   * Marketing (IHK)" fuer "Marketingmanager/in"). Reine Zusatzinfo fuer
   * Anzeige und Pitch — role_name ist IMMER die Berufsbezeichnung.
   */
  typische_weiterbildung?: string;
  skills: CatalogRoleSkill[];
}

